mapper.select:
SELECT n.id, n.user_id, n.workspace_id, n.type, n.title, n.body, n.ref_task_id, n.read_at, n.created_at,
       w.name AS workspace_name
FROM app_notification n
LEFT JOIN workspace w ON w.id = n.workspace_id
WHERE n.user_id = #{userId}
   AND n.workspace_id = #{workspaceId} 

ORDER BY n.id DESC
LIMIT #{limit}

SELECT COUNT(*) FROM app_notification n
WHERE n.user_id = #{userId} AND n.read_at IS NULL
   AND n.workspace_id = #{workspaceId}

mapper.update:
UPDATE app_notification n SET read_at = NOW()
WHERE n.user_id = #{userId} AND n.read_at IS NULL
   AND n.workspace_id = #{workspaceId}

mapper.select:
SELECT COUNT(*) FROM app_notification
WHERE workspace_id = #{workspaceId} AND user_id = #{userId}
  AND ref_task_id IS NULL AND type = #{type} AND created_at >= #{since}
